import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static long[][] Comb;
    static long[][] A, B, CC;
    static ArrayList<Pair>[][] P, Q;
    static int R, C, n;
    static long TT, MM, Res;
    static String p;

    static class Pair implements Comparable<Pair> {
        long first, second;
        Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }
        public int compareTo(Pair o) {
            if (this.first < o.first) return -1;
            if (this.first > o.first) return 1;
            return 0;
        }
    }

    static int lowerBound(ArrayList<Pair> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid).first < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static void put(int x, int y, long g, long c1, long c2, int ck) {
        if (x + y == n + R) {
            P[x][ck].add(new Pair(g, c1));
            if (c2 != 0) Q[x][ck].add(new Pair(g, c2));
            return;
        }
        put(x + 1, y, g + (ck == 0 ? A[x + 1][y] : 0), c1, (p.charAt(x + y) != 'B' ? c2 : 0), ck);
        put(x, y + 1, g + (ck == 1 ? B[x][y + 1] : 0), c1, (p.charAt(x + y) != 'A' ? c2 : 0), ck);
    }

    static void make(ArrayList<Pair> list) {
        if (list.isEmpty()) return;
        list.sort(Pair::compareTo);
        int cnt = 0;
        long s = 0;
        for (int i = 0; i < list.size(); i++) {
            s += list.get(i).second;
            if (i == list.size() - 1 || list.get(i).first != list.get(i + 1).first) {
                list.set(cnt++, new Pair(list.get(i).first, s));
                s = 0;
            }
        }
        while (list.size() > cnt) {
            list.remove(list.size() - 1);
        }
    }

    static void calc1(int x, int y, long g, int ck) {
        if (x + y == n + R) {
            ArrayList<Pair> list = P[x][ck];
            if (list.isEmpty()) return;
            int t = lowerBound(list, (TT + 1) / 2 - g);
            if (t < list.size() && list.get(t).second > 0) {
                long tp = (list.get(t).first + g) * 2 - TT;
            if (tp < 0) tp = -tp;
            if (MM > tp) MM = tp;
        }
        if (t > 0 && list.get(t - 1).second > 0) {
            long tp = (list.get(t - 1).first + g) * 2 - TT;
            if (tp < 0) tp = -tp;
            if (MM > tp) MM = tp;
        }
        return;
    }
    calc1(x - 1, y, g + (ck == 0 ? A[x][y] : 0), ck);
    calc1(x, y - 1, g + (ck == 1 ? B[x][y] : 0), ck);
}

static void calc2(int x, int y, long g, int ck) {
    if (x + y == n + R) {
        ArrayList<Pair> list = Q[x][ck];
        int t = lowerBound(list, (TT + 1) / 2 - g);
        if (t < list.size() && list.get(t).second > 0) {
            long tp = (list.get(t).first + g) * 2 - TT;
            if (tp < 0) tp = -tp;
            if (MM == tp) Res += list.get(t).second;
        }
        if (t > 0 && list.get(t-1).second > 0) {
            long tp = (list.get(t-1).first + g) * 2 - TT;
            if (tp < 0) tp = -tp;
            if (MM == tp) Res += list.get(t-1).second;
        }
        return;
    }
    if (p.charAt(x + y - 1) != 'B') {
        calc2(x-1, y, g + (ck == 0 ? A[x][y] : 0), ck);
    }
    if (p.charAt(x + y - 1) != 'A') {
        calc2(x, y-1, g + (ck == 1 ? B[x][y] : 0), ck);
    }
}

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    R = sc.nextInt();
    C = sc.nextInt();
    p = sc.next();
    n = R + C;

    int maxN = n;
    int maxComb = 2 * n;
    Comb = new long[maxComb + 2][maxComb + 2];
    A = new long[maxN + 1][maxN + 1];
    B = new long[maxN + 1][maxN + 1];
    CC = new long[maxN + 1][maxN + 1];
    P = new ArrayList[maxN + 1][2];
    Q = new ArrayList[maxN + 1][2];
    for (int i = 0; i <= maxN; i++) {
        for (int j = 0; j < 2; j++) {
            P[i][j] = new ArrayList<>();
            Q[i][j] = new ArrayList<>();
        }
    }

    for (int i = 0; i <= maxComb; i++) {
        Comb[i][0] = 1;
        for (int j = 1; j <= i && j <= maxComb; j++) {
            Comb[i][j] = Comb[i-1][j-1] + Comb[i-1][j];
        }
    }

    TT = Comb[n * 2][R * 2];

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i > 0) A[i][j] = Comb[i-1][R-1] * (Comb[n*2 - i][R] - Comb[j][R]);
            if (j > 0) B[i][j] = Comb[j-1][R-1] * (Comb[n*2 - j][R] - Comb[i][R]);
        }
    }

    CC[0][0] = 1;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i != n && p.charAt(i + j) != 'B') CC[i+1][j] += CC[i][j];
            if (j != n && p.charAt(i + j) != 'A') CC[i][j+1] += CC[i][j];
        }
    }

    for (int i = R; i <= n; i++) {
        if (p.charAt(i + R - 1) != 'B') put(R, i, A[R][i], Comb[i+R-1][R-1], CC[R-1][i], 0);
        if (p.charAt(i + R - 1) != 'A') put(i, R, B[i][R], Comb[i+R-1][R-1], CC[i][R-1], 1);
    }

    for (int i = R; i <= n; i++) {
        for (int j = 0; j < 2; j++) {
            make(P[i][j]);
            make(Q[i][j]);
        }
    }

    MM = TT + 1;
    calc1(n, n, 0, 0);
    calc1(n, n, 0, 1);
    calc2(n, n, 0, 0);
    calc2(n, n, 0, 1);
    System.out.println(Res);
}
}
